/* Session 10 drills (compute & scaling, the comparison layer). stub values must match SESSION.stub chip labels
   exactly. words must appear verbatim (case-insensitive) in q so they can be highlighted after submit. Every stem ends
   in an explicit question (drills-lint.js checks this for sessions numbered 10 and up).
   C1 (Exam Q43, tag K) comes from his baseline miss, reconstructed from the one-line summary in CONTEXT §3 (the
   original wording is not in the repo); its distractors differ from Session 4's drill Q43 (Route 53 / Global
   Accelerator there; an NLB per service, a Classic Load Balancer and Route 53 weighted records here). C2–C3 carry his
   prestige-distractor pattern (src 'Exam pattern', tag C): Global Accelerator and a second Region for a scaling
   problem (C2), Global Accelerator and Transit Gateway for an in-Region static-IP need (C3).
   No correct answer depends on a change after the exam guide: launch templates (C19's near-miss), NLB security groups,
   App Runner, Fargate sizes, price-capacity-optimized and Beanstalk Cluster Mode appear only in why/expl/update text.
   Correct positions as authored for the 28 single-answer drills: A 7 · B 7 · C 7 · D 7 (options are shuffled per
   attempt anyway). Select TWO: C14 = A + D, C29 = B + E. */
(function () {
  'use strict';
  const S = window.SESSION = window.SESSION || {};
  const _o = (t, ok, why) => ({ t, ok: !!ok, why });
  S.drills = [
    /* ---------------- his record ---------------- */
    { id: 'C1', src: 'Exam Q43', line: 'elb', mine: true, tag: 'K',
      q: 'A company runs three containerised services on Amazon EC2 instances in one AWS Region. Requests for /orders/* must go to the orders service, requests for /users/* to the users service, and every request to admin.example.com to the admin service. All traffic is HTTPS on one public endpoint. Which solution meets these requirements with the LEAST operational overhead?',
      opts: [_o('Put an Application Load Balancer in front with listener rules that send each path and the admin host name to its own target group.', 1, 'Path-based and host-based routing are ALB listener rules — built for exactly this, with nothing to run yourself.'),
        _o('Put a Network Load Balancer in front with one TLS listener per service, each on its own port, forwarding to that service’s instances.', 0, 'An NLB works at layer 4: it sees ports, not paths or host names, so clients would have to call three ports.'),
        _o('Put a Classic Load Balancer in front with one HTTPS listener and register the instances of all three services behind it directly.', 0, 'A CLB has no path or host rules and is the previous generation; every request would reach any service.'),
        _o('Create Amazon Route 53 weighted records for each service name, and point each record at the Elastic IP of that service’s instances.', 0, 'DNS sees names, never paths: /orders and /users share one name. No health-aware load balancing either.')],
      stub: { pat: 'none stated', trf: 'HTTP/HTTPS', ctl: 'containers', sup: 'least ops' }, words: ['/orders/*', '/users/*', 'admin.example.com', 'LEAST operational overhead'],
      expl: 'Your baseline **Q43**, tag K: “route by path” and “route by host” are the words of an **ALB** listener rule. An NLB reads ports, Route 53 reads names, a CLB reads neither.' },
    { id: 'C2', src: 'Exam pattern', line: 'asg', mine: true, tag: 'C',
      q: 'An online shop runs on Amazon EC2 instances in an Auto Scaling group behind an Application Load Balancer in one AWS Region, and all of its customers are in that country. During flash sales, CPU reaches 100% and requests time out for several minutes before new instances join. The group uses a simple scaling policy with a 300-second cooldown. Which change addresses the cause MOST directly?',
      opts: [_o('Put AWS Global Accelerator in front of the Application Load Balancer so that customer requests travel over the AWS global network.', 0, 'Prestige distractor: a faster network path does not add a single instance; the fleet is still too small during the spike.'),
        _o('Replace the simple scaling policy with target tracking on the ALB request count per target, so each spike scales out at once.', 1, 'Target tracking is not held by the cooldown and adds capacity in proportion to the load — the actual cause here.'),
        _o('Deploy a copy of the stack in a second AWS Region and add Amazon Route 53 latency-based records that split customers between the two.', 0, 'Prestige distractor: customers are in one country; a second Region doubles the cost and still scales slowly in each.'),
        _o('Raise the cooldown of the simple scaling policy to 600 seconds so that each scaling activity has more time to take effect.', 0, 'A longer cooldown makes the group wait even longer before the next scale-out — the opposite of what the spike needs.')],
      stub: { pat: 'spiky', trf: 'HTTP/HTTPS', ctl: 'none stated', sup: 'fastest' }, words: ['in one AWS Region', 'simple scaling policy with a 300-second cooldown', 'MOST directly'],
      expl: 'Your prestige pattern, scaling edition. Errors while instances boot = a **scaling** problem: a dynamic policy that reacts at once (target tracking). Global Accelerator and a second Region answer network and Region problems this shop does not have.' },
    { id: 'C3', src: 'Exam pattern', line: 'elb', mine: true, tag: 'C',
      q: 'A payment partner connects to a company’s TCP service on Amazon EC2 instances in one AWS Region. The partner’s firewall allows outbound traffic only to a fixed list of IP addresses that must never change. The instances run in two Availability Zones. Which solution is the MOST cost-effective?',
      opts: [_o('Put AWS Global Accelerator, with its two static anycast IP addresses, in front of a Network Load Balancer for the instances.', 0, 'Prestige distractor: it works, but Global Accelerator’s charges come on top of an NLB that already gives static IPs.'),
        _o('Attach the VPC to AWS Transit Gateway and give the partner the Elastic IP addresses of the NAT gateways in both Availability Zones.', 0, 'Prestige distractor: those IPs never change, but a NAT gateway carries only connections the instances start; nothing can connect in.'),
        _o('Put a Network Load Balancer with an Elastic IP per AZ in front of an Application Load Balancer that forwards to the instances.', 0, 'The IPs never change, but an ALB listens only for HTTP or HTTPS and cannot carry the partner’s raw TCP protocol.'),
        _o('Put a Network Load Balancer with a TCP listener in front of the instances, with an Elastic IP address in each Availability Zone.', 1, 'An NLB gives one static IP per AZ (an Elastic IP if you choose) and carries TCP — the built-for answer in one Region.')],
      stub: { pat: 'none stated', trf: 'TCP/UDP', ctl: 'none stated', sup: 'cheapest' }, words: ['TCP service', 'fixed list of IP addresses', 'MOST cost-effective'],
      expl: 'Your prestige pattern, load-balancing edition. Static IPs + TCP in one Region = **NLB** with an Elastic IP per AZ. Global Accelerator in front of the NLB also works, but it is built for global users and costs more; a NAT gateway lets nothing connect in; an ALB cannot carry raw TCP.' },

    /* ---------------- choosing ---------------- */
    { id: 'C4', src: 'New', line: 'choose',
      q: 'A team has packaged a stateless REST API as a Linux container image in Amazon ECR. Requests take under a second, traffic is steady through the day, and the team does not want to patch, scale or replace any servers. The API must sit behind an Application Load Balancer. Which solution has the LEAST operational overhead?',
      opts: [_o('Run the image on Amazon EC2 instances in an Auto Scaling group, starting the container from user data with Docker on every launch.', 0, 'It works, but the instances, their AMIs and their patches stay with the team — the overhead the stem rules out.'),
        _o('Run the image in an Amazon EKS cluster on a managed node group, with a Kubernetes Deployment and a Service of type LoadBalancer.', 0, 'Nodes to patch and a Kubernetes control plane to upgrade, with no Kubernetes need stated.'),
        _o('Run the image as an Amazon ECS service on AWS Fargate, with its tasks as IP targets in the load balancer’s target group.', 1, 'No servers at all: ECS keeps the desired count, Fargate runs the tasks, the ALB sends traffic to their IPs.'),
        _o('Run the image as an Amazon ECS service on an Auto Scaling group capacity provider of EC2 instances that the team keeps patched.', 0, 'ECS manages the tasks, but the EC2 container instances are still the team’s to patch and scale.')],
      stub: { pat: 'steady 24/7', trf: 'HTTP/HTTPS', ctl: 'containers', sup: 'least ops' }, words: ['container image', 'does not want to patch, scale or replace any servers', 'LEAST operational overhead'],
      expl: 'Containers + no servers + least ops = **ECS on Fargate**. EKS adds Kubernetes nobody asked for; EC2 capacity brings the servers back.' },
    { id: 'C5', src: 'New', line: 'choose',
      q: 'A company is moving a licensed analytics application from its data centre. The vendor requires a host-based security agent that loads a kernel module, and support is per instance. The application runs all day on a fixed number of servers, and failed servers must be replaced automatically. Which compute option meets these requirements?',
      opts: [_o('Amazon EC2 instances in an Auto Scaling group, launched from a launch template whose AMI includes the agent and its kernel module.', 1, 'Full OS access for the kernel module, and the group replaces failed instances — the built-for answer for OS-level needs.'),
        _o('An Amazon ECS service on AWS Fargate, with the agent in a privileged sidecar container that loads the kernel module into each task.', 0, 'Fargate does not run privileged containers or give access to the host kernel.'),
        _o('An AWS Lambda function packaged as a container image that includes the agent, called by an Amazon EventBridge rule all day long.', 0, 'No OS or kernel to load a module into, and a 15-minute limit for an application that runs all day.'),
        _o('An Amazon EKS cluster on AWS Fargate, with the agent deployed as a DaemonSet so that one copy runs beside every pod of the app.', 0, 'EKS on Fargate supports neither DaemonSets nor privileged pods.')],
      stub: { pat: 'steady 24/7', trf: 'none stated', ctl: 'OS access', sup: 'none stated' }, words: ['loads a kernel module', 'replaced automatically'],
      expl: 'A kernel module needs the **OS**: EC2. An Auto Scaling group keeps the count and replaces failures. Fargate and Lambda hide the host; that is their point.' },

    /* ---------------- EC2 ---------------- */
    { id: 'C6', src: 'New', line: 'ec2',
      q: 'A company runs a self-managed in-memory database on Amazon EC2. Each node keeps a 400 GiB working set in RAM and uses little CPU, and the nodes run around the clock. The current general purpose instances are sized for memory and leave most vCPUs idle. Which instance family is the BEST fit?',
      opts: [_o('Compute optimized instances, which give the most vCPUs for the price so the database answers each query faster.', 0, 'The database is memory-bound and its vCPUs are idle; more CPU per dollar buys nothing here.'),
        _o('Memory optimized instances, which give the most RAM per vCPU for large data sets that are processed in memory.', 1, 'Built for in-memory databases: the RAM you need without paying for idle vCPUs.'),
        _o('Storage optimized instances, whose local NVMe disks give high sequential read and write throughput to the data.', 0, 'Built for heavy I/O to local disks; this working set lives in RAM, not on disk.'),
        _o('Burstable T instances in unlimited mode, which bank CPU credits while idle and burst whenever queries arrive.', 0, 'Burstable instances solve spiky CPU, not a 400 GiB memory need.')],
      stub: { pat: 'steady 24/7', trf: 'none stated', ctl: 'OS access', sup: 'none stated' }, words: ['in-memory database', '400 GiB working set in RAM', 'BEST fit'],
      expl: 'RAM-bound, CPU idle = **memory optimized**. Match the family to the resource the workload is short of.' },
    { id: 'C7', src: 'New', line: 'ec2',
      q: 'A research team runs a tightly coupled computational fluid dynamics simulation that uses MPI across 64 Amazon EC2 instances. The nodes exchange data constantly, and the job’s runtime is dominated by network latency between them. Which deployment gives the LOWEST latency between the nodes?',
      opts: [_o('A spread placement group across three Availability Zones, so that each instance runs on its own rack with its own power.', 0, 'Spread groups separate instances for availability — the opposite of close — and hold at most seven per AZ.'),
        _o('A partition placement group with seven partitions in one Availability Zone, so that nodes share racks within a partition.', 0, 'Partitions isolate racks from each other for fault tolerance; they are not built for the lowest node-to-node latency.'),
        _o('A cluster placement group spanning two Availability Zones, so that half of the nodes keep running if one zone fails.', 0, 'A cluster placement group cannot span Availability Zones; it exists in one AZ only.'),
        _o('A cluster placement group in one Availability Zone, with instances that support the Elastic Fabric Adapter for MPI.', 1, 'One AZ, one high-bandwidth segment, and OS-bypass networking for MPI: built for tightly coupled HPC.')],
      stub: { pat: 'short jobs', trf: 'none stated', ctl: 'OS access', sup: 'fastest' }, words: ['tightly coupled', 'MPI', 'LOWEST latency'],
      expl: 'Tightly coupled + MPI + latency = **cluster placement group** (one AZ) + **EFA**. Spread and partition groups are about failure, not speed.' },
    { id: 'C8', src: 'New', line: 'ec2',
      q: 'A company is deploying a 300-node Apache Cassandra cluster on Amazon EC2 in one Availability Zone. Cassandra must know which nodes share hardware so that it places replicas on different racks. A single rack failure must never take out every replica of the data. Which placement strategy meets these requirements?',
      opts: [_o('A spread placement group with all 300 nodes, so that every node runs on its own rack with its own network and power.', 0, 'A spread group holds at most seven running instances per AZ; the eighth does not launch.'),
        _o('A cluster placement group with all 300 nodes, so that replication traffic between the nodes has the highest throughput.', 0, 'One high-bandwidth segment concentrates the nodes; nothing guarantees replicas on separate racks.'),
        _o('A partition placement group with seven partitions, with Cassandra’s rack setting mapped to each partition number.', 1, 'Partitions share no racks, scale to hundreds of instances, and expose the partition so Cassandra can place replicas.'),
        _o('No placement group, with the 300 nodes launched from one Auto Scaling group that balances them across instance types.', 0, 'EC2 decides where they land and tells Cassandra nothing about racks.')],
      stub: { pat: 'steady 24/7', trf: 'none stated', ctl: 'OS access', sup: 'most resilient' }, words: ['300-node', 'know which nodes share hardware', 'single rack failure'],
      expl: 'Large, rack-aware, replicated (Cassandra, HDFS, HBase) = **partition** placement group. Spread is for a handful of critical instances.' },
    { id: 'C9', src: 'New', line: 'ec2',
      q: 'A company will move a database that is licensed per physical CPU socket under its existing agreement to Amazon EC2. The licence terms require proof of the sockets and cores used and that an instance returns to the same physical server after a stop. Which tenancy meets these requirements?',
      opts: [_o('Amazon EC2 Dedicated Hosts, with host affinity set so that each instance restarts on the host it was placed on.', 1, 'Hosts show sockets and cores, and affinity keeps an instance on the same physical server — built for this.'),
        _o('Amazon EC2 Dedicated Instances, which run on hardware dedicated to the company’s account and to no other customer.', 0, 'Isolated hardware, but no view of sockets or cores and no control over which server an instance lands on.'),
        _o('Default shared tenancy, with the licence counted in AWS License Manager by vCPU from the instance metadata.', 0, 'Shared hardware cannot prove physical sockets; the licence is server-bound.'),
        _o('An On-Demand Capacity Reservation in one Availability Zone for the database instances, with default tenancy.', 0, 'It reserves capacity, not a physical server; instances may land on any shared host.')],
      stub: { pat: 'steady 24/7', trf: 'none stated', ctl: 'OS access', sup: 'none stated' }, words: ['licensed per physical CPU socket', 'same physical server after a stop'],
      expl: 'Server-bound licence (sockets, cores, affinity) = **Dedicated Host**. Dedicated Instances isolate, but show nothing about the server.' },

    /* ---------------- purchase options ---------------- */
    { id: 'C10', src: 'New', line: 'buy',
      q: 'A company runs 40 m-family Amazon EC2 instances in one AWS Region around the clock. They serve customers and must not be interrupted. The architecture team is certain the workload will stay on that instance family in that Region for the next three years, though sizes may change. The company wants the largest discount. Which purchase option is the MOST cost-effective?',
      opts: [_o('A three-year Compute Savings Plan for the hourly spend of the 40 instances, which also covers any other family or Region.', 0, 'Up to 66%: flexibility the team says it will not use, paid for with a smaller discount.'),
        _o('A three-year EC2 Instance Savings Plan for the m family in that Region, covering the hourly spend of the 40 instances.', 1, 'Up to 72% for one family in one Region, any size — the deepest discount for a workload that will not move.'),
        _o('An On-Demand Capacity Reservation for the 40 instances in one Availability Zone, kept for the full three years.', 0, 'It guarantees capacity but gives no discount on its own.'),
        _o('Spot Instances for all 40, with an Auto Scaling group that relaunches any instance reclaimed with two minutes’ notice.', 0, 'Deeper still, but a reclaim interrupts instances that serve customers and must not be interrupted.')],
      stub: { pat: 'steady 24/7', trf: 'none stated', ctl: 'none stated', sup: 'cheapest' }, words: ['must not be interrupted', 'stay on that instance family in that Region', 'next three years', 'MOST cost-effective'],
      expl: 'Must not be interrupted rules out Spot. Steady, fixed family and Region, three years, deepest discount = **EC2 Instance Savings Plan** (up to 72%). A Compute Savings Plan pays for flexibility that is not needed.' },
    { id: 'C11', src: 'New', line: 'buy',
      q: 'A company spends a steady amount every hour on Amazon EC2 instances of several families. Over the next year it will move most of the workload to Amazon ECS on AWS Fargate and some of it to AWS Lambda. It wants to commit for three years and keep the discount through the move. Which commitment meets these requirements?',
      opts: [_o('A three-year EC2 Instance Savings Plan for the family the company uses most, so the largest share keeps the bigger discount.', 0, 'It applies only to that EC2 family in one Region; Fargate and Lambda usage would not be covered.'),
        _o('Three-year Standard Reserved Instances for the current instance types, to be sold in the Marketplace after the move.', 0, 'They cover only those EC2 instances, and a resale is not a discount on Fargate or Lambda.'),
        _o('Three-year Convertible Reserved Instances for the current instances, exchanged for other instance families during the move.', 0, 'Exchanges stay inside EC2; a Convertible RI never applies to Fargate or Lambda.'),
        _o('A three-year Compute Savings Plan for the steady hourly spend, applied to EC2, Fargate and Lambda usage as the mix changes.', 1, 'Compute Savings Plans follow the spend across families, Regions, Fargate and Lambda.')],
      stub: { pat: 'steady 24/7', trf: 'none stated', ctl: 'containers', sup: 'cheapest' }, words: ['move most of the workload to Amazon ECS on AWS Fargate', 'keep the discount through the move'],
      expl: 'A commitment that must survive a move to Fargate and Lambda = **Compute Savings Plan**. Everything else is tied to EC2 instances.' },
    { id: 'C12', src: 'New', line: 'buy',
      q: 'A ticketing company expects one sales event in six weeks and needs 40 c-family Amazon EC2 instances guaranteed in one Availability Zone for its two-week duration. It does not want any commitment longer than the event, and the instances must start immediately when needed. Which option meets these requirements?',
      opts: [_o('An On-Demand Capacity Reservation for 40 instances in that Availability Zone, cancelled when the event ends.', 1, 'Capacity held in one AZ for any duration, with no term for an immediate-use reservation — built for scaling events.'),
        _o('A one-year Compute Savings Plan sized for the hourly cost of 40 instances, bought just before the event begins.', 0, 'A discount, not capacity, and a commitment eleven months longer than the event.'),
        _o('Regional Reserved Instances for 40 instances of the type for one year, so that their price is fixed for the event.', 0, 'Regional RIs reserve no capacity, and the term is a year.'),
        _o('Spot Instances requested with a capacity-optimized allocation strategy for 40 instances during the two weeks.', 0, 'Spot capacity can be reclaimed at any time; nothing is guaranteed.')],
      stub: { pat: 'predictable peaks', trf: 'none stated', ctl: 'none stated', sup: 'none stated' }, words: ['guaranteed in one Availability Zone', 'does not want any commitment longer than the event'],
      expl: 'Guaranteed capacity, one AZ, no term = **On-Demand Capacity Reservation**. Savings Plans and Regional RIs change the bill, not the capacity.' },
    { id: 'C13', src: 'New', line: 'buy',
      q: 'A studio renders animation frames every night. Each frame takes about 10 minutes, the render software saves progress, and a failed frame is simply queued again. The work must finish by morning, but nothing else matters except cost. Which purchasing approach is the MOST cost-effective?',
      opts: [_o('On-Demand Instances in an Auto Scaling group that scales on the queue of frames and scales to zero when the night is over.', 0, 'It works and scales well, but pays the full price for work that tolerates interruption.'),
        _o('A one-year Compute Savings Plan sized for the night’s peak, with the instances running only while frames are waiting.', 0, 'A commitment billed every hour of the day for a fleet that runs only at night.'),
        _o('Spot Instances across several instance types and Availability Zones, with interrupted frames returned to the queue.', 1, 'Up to 90% off; frames are short, checkpointed and retried, so a reclaimed instance costs only minutes.'),
        _o('Dedicated Hosts reserved for the render fleet, so that each render node keeps the same physical server every night.', 0, 'Dedicated hardware costs more and solves licensing, not price.')],
      stub: { pat: 'interruptible', trf: 'none stated', ctl: 'none stated', sup: 'cheapest' }, words: ['saves progress', 'simply queued again', 'MOST cost-effective'],
      expl: 'Interruptible, retried, checkpointed, cheapest = **Spot**, diversified across types and AZs. Commitments suit work that runs all the time.' },
    { id: 'C14', src: 'New', line: 'buy',
      q: 'A stateless web application needs 20 Amazon EC2 instances at all times, and the baseline must never be interrupted. On several afternoons a month, unpredictable spikes need up to 40 more instances for a few hours; extra instances that are interrupted are simply replaced. The company wants the MOST cost-effective design. Which TWO actions should the company take?',
      opts: [_o('Buy a Compute Savings Plan sized for the hourly spend of the 20 instances that run at all times.', 1, 'The steady baseline gets a commitment discount; nothing in it can be interrupted.'),
        _o('Buy Standard Reserved Instances for 60 instances so that every spike is also covered at the lower price.', 0, 'You pay for 60 instances every hour to cover 40 that run a few hours a month.'),
        _o('Create an On-Demand Capacity Reservation for 60 instances so the spike capacity is always available.', 0, 'Reserved capacity is billed whether used or not, and it gives no discount by itself.'),
        _o('Use a mixed instances policy with an On-Demand base of 20 and Spot Instances for all capacity above it.', 1, 'The base stays On-Demand (covered by the plan); the spike runs on Spot, and lost instances are replaced.'),
        _o('Run all 60 instances on Spot with the capacity-optimized allocation strategy across several types.', 0, 'The baseline must never be interrupted; Spot can be reclaimed at any time.')],
      stub: { pat: 'spiky', trf: 'none stated', ctl: 'none stated', sup: 'cheapest' }, words: ['baseline must never be interrupted', 'unpredictable spikes', 'MOST cost-effective', 'Which TWO'],
      expl: 'Layer the options: a **Savings Plan** for the steady baseline, and **Spot above an On-Demand base** for the spikes — a mixed instances policy does the split.' },

    /* ---------------- Auto Scaling ---------------- */
    { id: 'C15', src: 'New', line: 'asg',
      q: 'A company runs a web tier in an Auto Scaling group. It wants the group to keep average CPU utilisation near 50% as the load changes during the day, without creating or tuning any CloudWatch alarms itself. Which scaling policy meets these requirements with the LEAST operational overhead?',
      opts: [_o('A step scaling policy with three CloudWatch alarm bands that add or remove one, two or three instances at each step.', 0, 'It can hold CPU near 50%, but the alarms and step sizes are yours to create and tune.'),
        _o('A target tracking scaling policy on the group’s average CPU utilisation with a target value of 50 percent.', 1, 'You name the metric and the target; Auto Scaling creates and manages the alarms, like a thermostat.'),
        _o('A scheduled action every hour that sets the desired capacity from last week’s CPU graph for the same hour.', 0, 'A clock, not a reaction: any change from last week is missed, and the schedule is yours to maintain.'),
        _o('A simple scaling policy that adds two instances when CPU exceeds 60%, followed by the default 300-second cooldown.', 0, 'One alarm per direction to manage, and the cooldown delays every further step.')],
      stub: { pat: 'none stated', trf: 'none stated', ctl: 'none stated', sup: 'least ops' }, words: ['keep average CPU utilisation near 50%', 'without creating or tuning any CloudWatch alarms', 'LEAST operational overhead'],
      expl: '“Keep a metric near a value” = **target tracking**. Step and simple policies need alarms you manage; a schedule guesses.' },
    { id: 'C16', src: 'New', line: 'asg',
      q: 'A payroll application goes live tomorrow. Its users log in at exactly 08:00 on weekdays, as agreed in the contract, and new instances need 10 minutes to boot. The Auto Scaling group has no metric history yet. The company wants the extra capacity ready before 08:00 from the first day. Which approach meets these requirements?',
      opts: [_o('A predictive scaling policy in forecast and scale mode, so that capacity is launched before each forecast weekday peak.', 0, 'Predictive scaling needs at least 24 hours of data before it forecasts; there is none on day one.'),
        _o('A target tracking policy on CPU utilisation with a default instance warmup of 10 minutes for the new instances.', 0, 'It reacts after the load arrives; with 10-minute boots, the 08:00 rush still waits.'),
        _o('A simple scaling policy on a CloudWatch alarm for the login count, with a cooldown that matches the boot time.', 0, 'Still reactive and slowed by the cooldown; capacity comes after the users do.'),
        _o('A recurring scheduled action that raises the desired capacity at 07:45 on weekdays and lowers it after the morning.', 1, 'The time is known in advance: a schedule launches the instances before 08:00, with no history needed.')],
      stub: { pat: 'predictable peaks', trf: 'none stated', ctl: 'none stated', sup: 'none stated' }, words: ['exactly 08:00 on weekdays', 'no metric history yet', 'from the first day'],
      expl: 'A known time, no history = **scheduled action**. Predictive scaling is the near-miss: it needs 24 hours of data and learns a pattern; here the pattern is in the contract.' },
    { id: 'C17', src: 'New', line: 'asg',
      q: 'Worker instances in an Auto Scaling group process messages from an Amazon SQS queue; each message takes about 0.1 seconds. The business accepts a delay of 10 seconds for any message. Queue depth swings from almost nothing to thousands of messages within minutes. Which scaling configuration meets these requirements?',
      opts: [_o('A target tracking policy on a backlog-per-instance metric, with a target of 100 messages per InService instance.', 1, 'Backlog per instance follows both the queue and the fleet; 10 s ÷ 0.1 s gives the target of 100.'),
        _o('A target tracking policy on the queue’s ApproximateNumberOfMessages metric with a target value of 100 messages.', 0, 'Queue length alone ignores how many instances share it, so the group keeps adding instances while the queue drains.'),
        _o('A target tracking policy on the group’s average CPU utilisation with a target value of 50 percent for the workers.', 0, 'CPU lags the backlog; a growing queue of light messages can leave CPU low.'),
        _o('A scheduled action that doubles the desired capacity during business hours and halves it again every evening.', 0, 'The swings come within minutes, not on a clock.')],
      stub: { pat: 'spiky', trf: 'none stated', ctl: 'none stated', sup: 'none stated' }, words: ['0.1 seconds', 'delay of 10 seconds', 'within minutes'],
      expl: 'Scale queue workers on **backlog per instance**; target = acceptable latency ÷ processing time = 10 / 0.1 = **100**. Queue length alone over-scales.' },
    { id: 'C18', src: 'New', line: 'asg',
      q: 'An application on Amazon EC2 instances in an Auto Scaling group sits behind an Application Load Balancer. After a memory leak, some instances keep running but answer every request with an HTTP 500 error. The load balancer marks them unhealthy, yet the group never replaces them. Which change makes the group replace these instances automatically?',
      opts: [_o('Raise the group’s health check grace period to 900 seconds so that new instances have more time before checks begin.', 0, 'The grace period only delays checks on new instances; the group still ignores what the load balancer sees.'),
        _o('Add an EC2 status check alarm with an EC2 action that reboots each instance whose system status check has failed.', 0, 'The instances pass their EC2 status checks — they are running; only the application fails.'),
        _o('Turn on Elastic Load Balancing health checks for the Auto Scaling group, keeping a grace period that covers boot time.', 1, 'With ELB health checks on, an instance the load balancer reports unhealthy is replaced by the group.'),
        _o('Set the target group’s deregistration delay to zero seconds so that unhealthy instances leave the load balancer faster.', 0, 'It changes draining time, not whether the group replaces the instance.')],
      stub: { pat: 'none stated', trf: 'HTTP/HTTPS', ctl: 'none stated', sup: 'most resilient' }, words: ['keep running but answer every request with an HTTP 500 error', 'never replaces them'],
      expl: 'By default a group uses **EC2 status checks** only. A running instance that fails requests is replaced once **ELB health checks** are turned on for the group.' },
    { id: 'C19', src: 'New', line: 'asg',
      q: 'An Auto Scaling group runs an application that needs 8 minutes of bootstrap scripts and cache loading before it can serve. Traffic spikes arrive without warning, and during each spike users see errors until new instances are ready. The company wants new capacity to serve as quickly as possible. Which solution meets these requirements?',
      opts: [_o('Create a new launch configuration with a larger instance type, so that the bootstrap scripts finish in less time on each boot.', 0, 'Launch configurations take no new instance types and new accounts cannot create them; a bigger type barely shortens loading.'),
        _o('Add a warm pool of pre-initialised instances in the Stopped state, so that scale-out starts an instance already prepared.', 1, 'The 8 minutes are spent before the spike; scale-out only starts a prepared instance.'),
        _o('Add a predictive scaling policy in forecast and scale mode, so that instances are launched before each spike that is forecast.', 0, 'Predictive scaling learns recurring patterns; spikes that arrive without warning are not in the forecast.'),
        _o('Add a launch lifecycle hook that holds each new instance in Pending:Wait until its bootstrap scripts report that they have finished.', 0, 'A hook keeps unready instances out of service, which is good — but the 8 minutes still pass during the spike.')],
      stub: { pat: 'spiky', trf: 'none stated', ctl: 'none stated', sup: 'fastest' }, words: ['8 minutes of bootstrap', 'without warning', 'as quickly as possible'],
      expl: 'Slow boot + unpredictable spikes = **warm pool**: do the slow part ahead of time. A lifecycle hook makes waiting safe, not shorter; predictive scaling needs a pattern.' },

    /* ---------------- load balancers ---------------- */
    { id: 'C20', src: 'New', line: 'elb',
      q: 'A bank’s on-premises firewall allows outbound HTTPS only to two fixed IP addresses. The bank calls a company’s web application in one AWS Region, which must send /statements/* and /payments/* requests to different target groups of Amazon EC2 instances. Which solution meets both requirements?',
      opts: [_o('An Application Load Balancer with path rules for the two target groups and an Elastic IP address attached to each of its nodes.', 0, 'An ALB cannot take Elastic IPs; its addresses change behind its DNS name.'),
        _o('A Network Load Balancer with one Elastic IP in each of two Availability Zones and a listener rule for each URL path.', 0, 'An NLB cannot route by URL path or host name; its rules do not read the request.'),
        _o('A Network Load Balancer with an Elastic IP in each of two zones, forwarding to an Application Load Balancer that routes by path.', 1, 'The NLB gives two static IPs; its ALB-type target group hands the traffic to an ALB that routes by path.'),
        _o('An Amazon CloudFront distribution in front of an Application Load Balancer, with one cache behaviour for each of the two URL paths.', 0, 'CloudFront edge addresses are many and change; the bank cannot allow-list two of them.')],
      stub: { pat: 'none stated', trf: 'HTTP/HTTPS', ctl: 'none stated', sup: 'none stated' }, words: ['two fixed IP addresses', '/statements/*', '/payments/*'],
      expl: 'Static IPs (NLB) **and** path routing (ALB) = an **NLB with an ALB-type target group**. Neither load balancer does both alone.' },
    { id: 'C21', src: 'New', line: 'elb',
      q: 'A game studio runs multiplayer servers on Amazon EC2 instances that receive player traffic over UDP on port 7777. The servers ban cheaters by their IP address, so they must see each player’s original source IP. Traffic reaches millions of packets per second at peak. Which load balancer meets these requirements?',
      opts: [_o('An Application Load Balancer with an HTTPS listener and the X-Forwarded-For header that carries each player’s IP address.', 0, 'An ALB handles HTTP and HTTPS only; UDP game traffic never reaches it.'),
        _o('A Classic Load Balancer with a TCP listener on port 7777 and proxy protocol turned on for the client address.', 0, 'A CLB has no UDP listener and is the previous generation.'),
        _o('An Amazon API Gateway WebSocket API that forwards each player connection to the game servers on port 7777.', 0, 'WebSocket APIs carry messages over HTTPS, not raw UDP packets at this rate.'),
        _o('A Network Load Balancer with a UDP listener on port 7777 and instance targets, which keep the client source IP.', 1, 'Layer 4, UDP and the client IP preserved: built for this.')],
      stub: { pat: 'none stated', trf: 'TCP/UDP', ctl: 'OS access', sup: 'none stated' }, words: ['UDP on port 7777', 'original source IP'],
      expl: 'UDP + client IP = **NLB**. An ALB is HTTP only; CLB and API Gateway are not built for raw UDP.' },
    { id: 'C22', src: 'New', line: 'elb',
      q: 'A Network Load Balancer spreads TCP connections over two Availability Zones. One zone has 2 targets and the other has 8. Clients reach both load balancer nodes equally, and the 2 targets are overloaded while the other 8 are mostly idle. Which change spreads the load evenly across all 10 targets?',
      opts: [_o('Change the target group’s routing algorithm to least outstanding requests so that new connections go to the idlest target.', 0, 'That algorithm is an ALB target group setting; an NLB uses a flow hash.'),
        _o('Turn on target group stickiness by source IP so that each client stays on the same target for all of its connections.', 0, 'Stickiness pins clients to targets; the 2 targets keep half of the clients.'),
        _o('Turn on cross-zone load balancing for the Network Load Balancer so that each node sends traffic to targets in both zones.', 1, 'With cross-zone off, each node serves only its own zone: 25% for each of 2 targets, 6.25% for each of 8. On: 10% each.'),
        _o('Associate an Elastic IP address with the load balancer node in each zone so that clients connect to the zones separately.', 0, 'Clients already split between the nodes; static addresses do not change where each node sends traffic.')],
      stub: { pat: 'none stated', trf: 'TCP/UDP', ctl: 'none stated', sup: 'none stated' }, words: ['2 targets and the other has 8', 'evenly across all 10 targets'],
      expl: 'NLB **cross-zone is off by default**: each node uses only its own zone’s targets. Turn it on and every target gets 10%.' },
    { id: 'C23', src: 'New', line: 'elb',
      q: 'A company must send all traffic entering its VPC through a fleet of third-party firewall appliances from its existing vendor, which run on Amazon EC2 and support the GENEVE protocol. The fleet must scale and survive the failure of an appliance without the applications changing. Which solution meets these requirements?',
      opts: [_o('A Network Load Balancer in front of the appliances, with each application’s route table pointing to the NLB’s private IP address.', 0, 'An NLB is not a route-table hop for transparent inspection; GENEVE appliances are built for the Gateway Load Balancer.'),
        _o('A Gateway Load Balancer in front of the appliance fleet, with Gateway Load Balancer endpoints in the route tables of the VPC.', 1, 'Built for third-party appliances: GENEVE on port 6081, health checks, scaling, and endpoints as the next hop.'),
        _o('AWS Network Firewall with stateful rule groups that copy the vendor’s rules, deployed in a dedicated inspection subnet.', 0, 'A managed AWS firewall — but the stem requires the vendor’s own appliances.'),
        _o('An Application Load Balancer in front of the appliances, with listener rules that forward every request to the appliance target group.', 0, 'An ALB terminates HTTP; it cannot pass all traffic through appliances transparently.')],
      stub: { pat: 'none stated', trf: 'inline appliances', ctl: 'none stated', sup: 'most resilient' }, words: ['third-party firewall appliances', 'GENEVE protocol'],
      expl: 'Third-party appliances inline + GENEVE = **Gateway Load Balancer**. The inspection designs around it are Session 3.' },

    /* ---------------- containers ---------------- */
    { id: 'C24', src: 'New', line: 'ecs',
      q: 'A company runs Amazon ECS services on an Auto Scaling group of EC2 container instances. The team spends hours each month patching AMIs and right-sizing the instances. The services are Linux containers that need no GPUs and no host access. Which change removes the instance management with the LEAST effort?',
      opts: [_o('Move the services to the Fargate capacity provider, so that each task runs on capacity that AWS manages.', 1, 'The tasks keep their definitions; the instances, AMIs and their sizing disappear.'),
        _o('Keep the EC2 instances and patch them automatically with AWS Systems Manager Patch Manager on a weekly window.', 0, 'Patching becomes automatic, but the instances and their sizing are still the team’s to run.'),
        _o('Rebuild the services as Kubernetes Deployments in Amazon EKS with managed node groups, on the same instance types.', 0, 'A rewrite into Kubernetes, and node groups are still instances to look after.'),
        _o('Move the services to Elastic Beanstalk’s Docker platform, with one environment and Auto Scaling group per service.', 0, 'Beanstalk still runs EC2 instances per environment; it is a different service to learn as well.')],
      stub: { pat: 'none stated', trf: 'none stated', ctl: 'containers', sup: 'least ops' }, words: ['patching AMIs and right-sizing the instances', 'no GPUs and no host access', 'LEAST effort'],
      expl: 'Same ECS services, no instances = switch the capacity provider to **Fargate**. Nothing in the stem needs EC2.' },
    { id: 'C25', src: 'New', line: 'eks',
      q: 'A company runs 60 microservices on an on-premises Kubernetes cluster, deployed with Helm charts and managed with kubectl and Kubernetes operators. It will move them to AWS and wants to keep its manifests, charts and tooling unchanged. Which service meets these requirements with the LEAST rework?',
      opts: [_o('Amazon ECS on AWS Fargate, with one task definition and one ECS service written for each of the 60 microservices.', 0, 'Every chart becomes a new task definition — the rework the stem wants to avoid.'),
        _o('Elastic Beanstalk with the Docker platform, using one environment for each microservice and its own load balancer.', 0, 'Sixty environments and none of the Kubernetes tooling or operators.'),
        _o('AWS Lambda functions packaged as container images, with one function for each of the 60 microservices.', 0, 'A different model with a 15-minute limit, and Helm charts mean nothing to it.'),
        _o('Amazon EKS, with the existing Helm charts deployed to the cluster and pods running on managed node groups.', 1, 'Managed Kubernetes: manifests, Helm charts, kubectl and operators work unchanged.')],
      stub: { pat: 'none stated', trf: 'none stated', ctl: 'Kubernetes', sup: 'least ops' }, words: ['Helm charts', 'kubectl', 'LEAST rework'],
      expl: 'Kubernetes in, Kubernetes out = **EKS**. ECS is the least-ops answer only when nothing names Kubernetes.' },
    { id: 'C26', src: 'New', line: 'ecs',
      q: 'A company serves machine learning inference from a container that needs one NVIDIA GPU per task. It already runs its other services on Amazon ECS with AWS Fargate and wants to keep ECS for scheduling, scaling and deployments. Which capacity should the inference service use?',
      opts: [_o('The Fargate capacity provider, with a task definition that requests one GPU and the largest task size available.', 0, 'Fargate offers no GPUs, whatever the task size.'),
        _o('The FARGATE_SPOT capacity provider, which runs tasks on spare capacity that includes GPU-equipped hosts.', 0, 'Fargate Spot is Fargate at a discount: still no GPUs, and interruptions on top.'),
        _o('An Auto Scaling group capacity provider of GPU EC2 instances, with the task definition asking for one GPU.', 1, 'ECS schedules GPU tasks onto EC2 instances that have GPUs; Fargate cannot.'),
        _o('An AWS Lambda function packaged as a container image with the GPU drivers, called from the ECS services.', 0, 'Lambda has no GPUs either, and it would leave ECS for this service.')],
      stub: { pat: 'none stated', trf: 'none stated', ctl: 'containers', sup: 'none stated' }, words: ['one NVIDIA GPU per task', 'keep ECS'],
      expl: 'GPU containers on ECS = **EC2 capacity** (an Auto Scaling group capacity provider). Fargate and Lambda have no GPUs.' },
    { id: 'C27', src: 'New', line: 'ecs',
      q: 'A new Amazon ECS task on AWS Fargate starts normally: it pulls its image from Amazon ECR and its logs appear in CloudWatch Logs. When the application code tries to write to an Amazon DynamoDB table, it receives an AccessDenied error. Which change fixes the error?',
      opts: [_o('Add the DynamoDB write permissions to the task execution role that the task definition names for the Fargate agent.', 0, 'The execution role is for the agent (image pull, logs, secrets); the application never uses its credentials.'),
        _o('Add the DynamoDB write permissions to the task role that the task definition names for the application’s containers.', 1, 'The task role is what the code in the container calls AWS with.'),
        _o('Add the DynamoDB write permissions to the EC2 instance profile of the cluster, so that every task on it can use them.', 0, 'A Fargate task has no EC2 instance profile; that is the EC2 launch model.'),
        _o('Add a repository policy in Amazon ECR that allows the task to call DynamoDB with the image’s pull credentials.', 0, 'ECR policies govern image pulls; they grant nothing on DynamoDB.')],
      stub: { pat: 'none stated', trf: 'none stated', ctl: 'containers', sup: 'none stated' }, words: ['pulls its image from Amazon ECR', 'application code', 'AccessDenied'],
      expl: 'Image pull and logs work = the **execution role** is fine. The code’s own calls use the **task role**.' },

    /* ---------------- Lambda vs containers ---------------- */
    { id: 'C28', src: 'New', line: 'lambda',
      q: 'Each video uploaded to an Amazon S3 bucket must be transcoded, which takes about 40 minutes with an existing container image. Uploads arrive a few times an hour at random. The company does not want to run or patch any servers. Which solution meets these requirements?',
      opts: [_o('An Amazon EventBridge rule on the S3 upload event that runs an Amazon ECS task on AWS Fargate for each video.', 1, 'A Fargate task runs as long as the transcode needs, starts per upload and leaves nothing running in between.'),
        _o('An AWS Lambda function packaged from the same container image, invoked by the S3 upload event for each new video.', 0, 'Lambda stops at 15 minutes; a 40-minute transcode never finishes.'),
        _o('An AWS Lambda function with the maximum memory setting, which makes the transcode fast enough to fit in one run.', 0, 'More memory adds CPU, but the 15-minute timeout stays; a 40-minute job cannot count on fitting.'),
        _o('An Amazon EC2 instance that runs the container all day and polls the bucket every minute for new uploaded videos.', 0, 'A server to run and patch, idle most of the hour.')],
      stub: { pat: 'short jobs', trf: 'none stated', ctl: 'containers', sup: 'least ops' }, words: ['about 40 minutes', 'does not want to run or patch any servers'],
      expl: 'Longer than **15 minutes** rules out Lambda. Event-started container, no servers = **Fargate task** (or a Batch job). Lambda limits: Session 9 ch8.' },

    /* ---------------- Elastic Beanstalk ---------------- */
    { id: 'C29', src: 'New', line: 'paas',
      q: 'A company deploys a web application with AWS Elastic Beanstalk to a load-balanced production environment. New versions must be deployed with no reduction in serving capacity, and if a version fails its health checks the company must be able to return to the old version quickly. Which TWO deployment approaches meet these requirements?',
      opts: [_o('An all at once deployment that updates every instance in the environment at the same time.', 0, 'Every instance is out of service during the update: downtime, not full capacity.'),
        _o('An immutable deployment that launches the new version on new instances in a separate Auto Scaling group.', 1, 'Old instances keep serving until the new ones pass; rollback is terminating the new group.'),
        _o('A rolling deployment that updates the instances in batches of 25%, one batch after another.', 0, 'Each batch is out of service while it updates: capacity drops by a quarter.'),
        _o('A rolling with additional batch deployment, redeploying the old version the same way to roll back.', 0, 'Full capacity, yes — but rolling back means another full rolling deployment.'),
        _o('A blue/green deployment to a cloned environment, followed by a swap of the environment URLs.', 1, 'The old environment keeps running untouched; swapping the URLs back is the rollback.')],
      stub: { pat: 'none stated', trf: 'HTTP/HTTPS', ctl: 'code only', sup: 'most resilient' }, words: ['no reduction in serving capacity', 'return to the old version quickly', 'Which TWO'],
      expl: 'Full capacity + fast rollback = **immutable** (separate Auto Scaling group) or **blue/green** (swap environment URLs; keep the old one until DNS expires).' },

    /* ---------------- AWS Batch ---------------- */
    { id: 'C30', src: 'New', line: 'batch',
      q: 'A genomics lab submits about 5,000 containerised analysis jobs every week. Each job runs for 1 to 3 hours, some jobs must wait for others to finish, and an interrupted job can simply be retried. The lab has no staff to build or operate a scheduler and wants low compute prices. Which solution has the LEAST operational overhead?',
      opts: [_o('AWS Step Functions with a Map state that invokes one AWS Lambda function for every job and retries any that fail.', 0, 'Lambda stops at 15 minutes; jobs of 1 to 3 hours never finish.'),
        _o('An Amazon SQS queue with an Auto Scaling group of Spot workers and a custom script that tracks the job dependencies.', 0, 'It can work, but the scheduler, the dependency logic and the retries are code the lab must build and run.'),
        _o('An Amazon EMR cluster on Spot task nodes that runs each analysis container as a step submitted by the scientists.', 0, 'EMR is built for big data frameworks, not for scheduling thousands of independent containers with dependencies.'),
        _o('AWS Batch job queues with job dependencies, on a managed compute environment of Spot Instances that Batch scales.', 1, 'Batch queues, orders, retries and scales Spot capacity for jobs of any length — built for this.')],
      stub: { pat: 'interruptible', trf: 'none stated', ctl: 'containers', sup: 'least ops' }, words: ['1 to 3 hours', 'must wait for others to finish', 'LEAST operational overhead'],
      expl: 'Thousands of long jobs + dependencies + retries + Spot = **AWS Batch**. Lambda breaks on 15 minutes; a home-made queue and fleet is Batch rebuilt by hand.' }
  ];
})();
